installer-gui-script.script:
function checkRemoval() {
  if (!system.files.fileExistsAtPath('/Library/Application Support/Rollo USB Pacing/recovery.json')) return true;
  my.result.type = 'Fatal';
  my.result.title = 'Recovery needed first';
  my.result.message = 'Recover the interrupted setup using the administrator guide before removing the repair.';
  return false;
}
